import{_ as e,o as r,c as a,ag as o}from"./chunks/framework.Dk8PTAaz.js";const g=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1788616892000}'),d={name:"guide/introduction.md"};function n(i,t,l,s,h,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p><code>@meng-xi/unix-router</code> 是一个为 <strong>uni-app x</strong> 提供的路由管理库，API 风格对标 <strong>vue-router 4</strong>，但基于 uni-app x 的<strong>静态页面模型</strong>（<code>.uvue</code> 页面 + <code>pages.json</code> 注册 + <code>uni.*</code> 原生导航）编写，核心语言为 <strong>UTS</strong>（<code>.uts</code>）。</p><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p>uni-app x 原生提供了 <code>uni.navigateTo / redirectTo / reLaunch / navigateBack / switchTab</code>，当页面增多后直接使用这些 API 会有明显痛点：</p><ul><li><strong>无路由表</strong>：页面路径散落各处，无集中管理，缺少命名路由与类型提示。</li><li><strong>无守卫</strong>：无法在跳转前统一做登录校验、埋点等逻辑。</li><li><strong>无路由状态</strong>：没有统一的 <code>currentRoute</code> 响应式对象，难以在组合式 API 中追踪当前页。</li><li><strong>参数传递繁琐</strong>：对象类型参数难以跨页传递，查询解析需要手写。</li></ul><p>unix-router 用一套与 vue-router 一致的 API 抹平这些差异。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li><strong>刚从 uni-app（Vue3）迁到 uni-app x</strong>：用熟悉的路由写法快速过渡。</li><li><strong>页面已具规模、需要集中管理导航与鉴权</strong>：路由表 + 守卫让跳转链路清晰可控。</li><li><strong>希望跨 web / 小程序 / App 保持路由行为一致</strong>：一套 API 覆盖多端。</li></ul><h2 id="本指南如何带你「从入门到精通」" tabindex="-1">本指南如何带你「从入门到精通」 <a class="header-anchor" href="#本指南如何带你「从入门到精通」" aria-label="Permalink to &quot;本指南如何带你「从入门到精通」&quot;">​</a></h2><p>文档按递进式结构组织，建议按顺序阅读：</p><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>你将掌握</th></tr></thead><tbody><tr><td>🟢 <strong>入门</strong></td><td><a href="./getting-started.html">快速开始</a> → <a href="./route-config.html">路由配置</a> → <a href="./navigation.html">路由导航</a></td><td>从零跑通第一个跳转，理解路由表、四种导航与参数传递</td></tr><tr><td>🟢 <strong>入门</strong></td><td><a href="./../api/use-route.html">读取路由</a> / <a href="./composables.html">组合式 API</a></td><td><code>useRouter</code> / <code>useRoute</code> / <code>useLink</code> 与生命周期联动</td></tr><tr><td>🟡 <strong>进阶</strong></td><td><a href="./guards.html">路由守卫</a> → <a href="./meta.html">路由元信息</a></td><td>登录鉴权、<code>beforeEnter</code>、冷启动守卫、动态标题</td></tr><tr><td>🟡 <strong>进阶</strong></td><td><a href="./error-handling.html">错误处理</a> → <a href="./navigation-flow.html">导航流程</a></td><td>失败判定、全局错误捕获、理解一次导航的内部机制</td></tr><tr><td>🔴 <strong>精通</strong></td><td><a href="./recipes.html">完整实战</a> → <a href="./compatibility.html">平台兼容性</a></td><td>用一套模式搭出登录+TabBar+详情完整应用，掌握平台差异与常见坑</td></tr></tbody></table><blockquote><p><strong>提示</strong>：代码仓库内的 <a href="https://github.com/MengXi-Studio/unix-router/tree/master/packages/playground" target="_blank" rel="noreferrer"><code>packages/playground</code></a> 是一个可直接运行的 uni-app x 工程，内含 <code>pages/test</code> 功能自检页（程序化输出 PASS/FAIL），可边看文档边对照验证。</p></blockquote><h2 id="核心能力一览" tabindex="-1">核心能力一览 <a class="header-anchor" href="#核心能力一览" aria-label="Permalink to &quot;核心能力一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>路由匹配</td><td>path / name 双索引，字符串 / 对象 / 命名三种解析方式，严格模式</td></tr><tr><td>导航</td><td>push / replace / relaunch / back，自动识别 TabBar</td></tr><tr><td>守卫</td><td>beforeEach / beforeResolve / afterEach / beforeEnter / onBeforeRouteLeave 等</td></tr><tr><td>组合式 API</td><td>useRouter / useRoute / useLink</td></tr><tr><td>错误体系</td><td>RouterError / NavigationFailure / isNavigationFailure</td></tr><tr><td>扩展</td><td>guardRoute 冷启动守卫、重复导航拦截、守卫重定向 + 深度上限</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想立即动手？从<a href="./installation.html">安装</a>或<a href="./getting-started.html">快速开始</a>开始。</li><li>想了解设计取舍？查看<a href="./differences.html">与 vue-router 的差异</a>。</li></ul>',16)])])}const p=e(d,[["render",n]]);export{g as __pageData,p as default};
